PRAGMA foreign_keys=OFF;
BEGIN TRANSACTION;
CREATE TABLE game_locations (
        id INTEGER PRIMARY KEY,
        key TEXT UNIQUE NOT NULL,
        label TEXT NOT NULL,
        description TEXT,
        parent_id INTEGER REFERENCES game_locations(id),
        location_type TEXT DEFAULT 'macro' CHECK(location_type IN ('macro', 'sub')),
        rules TEXT,
        enemy_keys TEXT DEFAULT '[]',
        npc_keys TEXT DEFAULT '[]',
        is_active INTEGER DEFAULT 1,
        created_at TEXT DEFAULT (datetime('now')),
        updated_at TEXT DEFAULT (datetime('now'))
    , ai_generated INTEGER DEFAULT 0, approved INTEGER DEFAULT 1, map_x REAL DEFAULT NULL, map_y REAL DEFAULT NULL, map_icon TEXT NOT NULL DEFAULT 'town', visible_before_visit INTEGER NOT NULL DEFAULT 0, safe_for_rest INTEGER NOT NULL DEFAULT 0, review_status TEXT NOT NULL DEFAULT 'permanent', parent_key TEXT DEFAULT NULL, created_by TEXT NOT NULL DEFAULT 'admin_manual', location_subtype TEXT DEFAULT NULL, biome TEXT DEFAULT NULL, tier INTEGER NOT NULL DEFAULT 1, canonical INTEGER NOT NULL DEFAULT 0, usage_count INTEGER NOT NULL DEFAULT 0, source_campaign_id INTEGER NULL REFERENCES campaigns(id), temporary INTEGER NOT NULL DEFAULT 0, world_hex_q INTEGER, world_hex_r INTEGER, local_hex_q INTEGER, local_hex_r INTEGER, is_generic INTEGER NOT NULL DEFAULT 0, hex_type_key TEXT, image_url TEXT DEFAULT NULL);
COMMIT;
