INSERT INTO game_locations VALUES(1,'vilnograd_stolica','Vilnograd, Stolica','Wielka, kamienna stolica królestwa o szarych dachach i czarnych dymnych obłokach unoszących się nad dzielnicami rzemieślniczymi. Mury obronne pokrywa stary mech, a strażnicy w niebieskich pelerynach patrolują bramy o każdej godzinie.',NULL,'macro',NULL,'[]','[]',1,'2026-05-23 17:35:52','2026-05-30 13:22:26',0,1,NULL,NULL,'castle',0,1,'permanent',NULL,'seed','city','urban',1,1,2,NULL,0,NULL,NULL,NULL,NULL,0,NULL,NULL);
