INSERT INTO game_locations VALUES(162,'ruiny_pokrzywisk_kamienne_wej_cie','Ruiny Pokrzywisk: Kamienne Wejście','Porzucone, zarośnięte wejście do podziemi ruin dawnej wioski Pokrzywiska. Nadproże zdobi runa przekreślonego oka. Wnętrze spowite mrokiem i ciszą.',58,'sub',NULL,'[]','[]',1,'2026-05-25 12:07:49','2026-05-25 12:07:49',1,1,NULL,NULL,'town',0,0,'permanent','trzech_krukow','gm_runtime','ruin','forest',1,0,1,1099,0,NULL,NULL,NULL,NULL,0,NULL,NULL);
