INSERT INTO game_locations VALUES(188,'piwnice_starej_wie_y','Piwnice starej wieży','Wilgotne, mroczne podziemia pod wieżą; schody, drzwi z żelaznym okuciem, szczeliny prowadzące głębiej, zapach ziemi i zgniłej pleśni.',31,'sub',NULL,'[]','[]',1,'2026-05-25 18:20:10','2026-05-25 18:20:10',1,1,NULL,NULL,'town',0,0,'permanent','cieszowice_pole_lubek','gm_runtime','dungeon','underground',1,0,1,1100,0,NULL,NULL,NULL,NULL,0,NULL,NULL);
